use std::{fs, path::Path};

fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Loader only. All browser behavior is compiled from client/src/lib.rs.
    fs::write(
        "public/client/boot.js",
        "// Generated by the Rust build. WebAssembly loader only.\nimport init from './relay_landing_client.js';\nawait init();\n",
    )?;
    if Path::new("dist").exists() {
        fs::remove_dir_all("dist")?;
    }
    copy_directory(Path::new("public"), Path::new("dist"))?;
    fs::write(
        "dist/index.html",
        futures_executor::block_on(relay_landing::render())
            .map_err(|error| std::io::Error::other(error.to_string()))?,
    )?;
    // Pages advanced mode accepts an ES module directory with Wasm companions.
    fs::create_dir_all("dist/_worker.js")?;
    fs::copy("build/worker/shim.mjs", "dist/_worker.js/shim.js")?;
    fs::copy("build/worker/index.wasm", "dist/_worker.js/index.wasm")?;
    // Pages expects a handler object instead of the SDK's WorkerEntrypoint class.
    // Its fetch export already forwards directly to the Rust event handler.
    fs::write(
        "dist/_worker.js/index.js",
        "// Generated Pages adapter. Application logic is Rust.\nimport { fetch } from './shim.js';\nexport default { fetch };\n",
    )?;
    fs::write(
        "dist/_routes.json",
        r#"{"version":1,"include":["/","/api/*"],"exclude":[]}"#,
    )?;
    Ok(())
}

fn copy_directory(source: &Path, destination: &Path) -> std::io::Result<()> {
    fs::create_dir_all(destination)?;
    for entry in fs::read_dir(source)? {
        let entry = entry?;
        let target = destination.join(entry.file_name());
        if entry.file_type()?.is_dir() {
            copy_directory(&entry.path(), &target)?;
        } else {
            fs::copy(entry.path(), target)?;
        }
    }
    Ok(())
}
